# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.21.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.21.0/acs-0.21.0-aarch64-apple-darwin.tar.gz"
      sha256 "ae68f2ad5f470299e84a5e932c8a0b16b5a0c3a777a583adecb65b5805296a75"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.21.0/acs-0.21.0-x86_64-apple-darwin.tar.gz"
      sha256 "8494ddfd71fae78b1a8bbe27447a02053e49a7a4aceaaa637b9bbdb088e8f938"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.21.0/acs-0.21.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "27ca9c2441630ec71fb0038d7f971efc8f403b49bdd82ea5bd17e6c886112ed8"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.21.0/acs-0.21.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "bd8f7c6864e7b69c2212c38609ad7576374dba2be11ff99418d45860632996ae"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
